332: fn small_sort_network<T, F>(v: &mut [T], is_less: &mut F)
333: where
334:     T: FreezeMarker,
335:     F: FnMut(&T, &T) -> bool,
336: {
337:     // This implementation is tuned to be efficient for integer types.
338: 
339:     let len = v.len();
340:     if len < 2 {
341:         return;
342:     }
343: 
344:     if len > SMALL_SORT_NETWORK_SCRATCH_LEN {
345:         intrinsics::abort_immediate();
346:     }
347: 
348:     let mut stack_array = MaybeUninit::<[T; SMALL_SORT_NETWORK_SCRATCH_LEN]>::uninit();
349: 
350:     let len_div_2 = len / 2;
351:     let no_merge = len < 18;
352: 
353:     let v_base = v.as_mut_ptr();
354:     let initial_region_len = if no_merge { len } else { len_div_2 };
355:     // SAFETY: Both possible values of `initial_region_len` are in-bounds.
356:     let mut region = unsafe { slice::from_raw_parts_mut(v_base, initial_region_len) };
357: 
358:     // Avoid compiler unrolling, we *really* don't want that to happen here for binary-size reasons.
359:     loop {
360:         let presorted_len = if region.len() >= 13 {
361:             sort13_optimal(region, is_less);
362:             13
363:         } else if region.len() >= 9 {
364:             sort9_optimal(region, is_less);
365:             9
366:         } else {
367:             1
368:         };
369: 
370:         insertion_sort_shift_left(region, presorted_len, is_less);
371: 
372:         if no_merge {
373:             return;
374:         }
375: 
376:         if region.as_ptr() != v_base {
377:             break;
378:         }
379: 
380:         // SAFETY: The right side of `v` based on `len_div_2` is guaranteed in-bounds.
381:         unsafe { region = slice::from_raw_parts_mut(v_base.add(len_div_2), len - len_div_2) };
382:     }
383: 
384:     // SAFETY: We checked that T is Freeze and thus observation safe.
385:     // Should is_less panic v was not modified in parity_merge and retains it's original input.
386:     // scratch and v must not alias and scratch has v.len() space.
387:     unsafe {
388:         let scratch_base = stack_array.as_mut_ptr() as *mut T;
389:         bidirectional_merge(slice::from_raw_parts_mut(v_base, len), scratch_base, is_less);
390:         ptr::copy_nonoverlapping(scratch_base, v_base, len);
391:     }

