709: pub fn insertion_sort_shift_left<T, F: FnMut(&T, &T) -> bool>(
710:     v: &mut [T],
711:     offset: usize,
712:     is_less: &mut F,
713: ) {
714:     let len = v.len();
715:     if offset == 0 || offset > len {
716:         intrinsics::abort_immediate();
717:     }
718: 
719:     // SAFETY: see individual comments.
720:     unsafe {
721:         // We write this basic loop directly using pointers, as when we use a
722:         // for loop LLVM likes to unroll this loop which we do not want.
723:         // SAFETY: v_end is the one-past-end pointer, and we checked that
724:         // offset <= len, thus tail is also in-bounds.
725:         let v_base = v.as_mut_ptr();
726:         let v_end = v_base.add(len);
727:         let mut tail = v_base.add(offset);
728:         while tail != v_end {
729:             // SAFETY: v_base and tail are both valid pointers to elements, and
730:             // v_base < tail since we checked offset != 0.
731:             insert_tail(v_base, tail, is_less);
732: 
733:             // SAFETY: we checked that tail is not yet the one-past-end pointer.
734:             tail = tail.add(1);
735:         }
736:     }
737: }
